import { DeviceType } from "./deviceType";
import { useResizeObserver } from "./useResizeObserver";
const MobileContainerMaxWidth = 392;
const getContainerType = (width) => {
    if (width > MobileContainerMaxWidth) {
        return DeviceType.Desktop;
    }
    return DeviceType.Mobile;
};
export const useContainerTypeObserver = (container) => {
    const { result } = useResizeObserver({ target: container });
    const width = result && result.borderBoxSize[0].inlineSize;
    if (width === null) {
        return null;
    }
    return getContainerType(width);
};
